import { normalizeAnalyticsClientPlatform, } from "../shared/analytics-platform.js";
export function getAnalyticsClientPlatform(configured) {
    if (configured)
        return configured;
    if (typeof window === "undefined")
        return "web";
    const platformWindow = window;
    return (normalizeAnalyticsClientPlatform(platformWindow.agentNativeDesktop?.analytics?.clientPlatform) ??
        normalizeAnalyticsClientPlatform(platformWindow.__AGENT_NATIVE_HOST_PLATFORM__) ??
        normalizeAnalyticsClientPlatform(platformWindow.__AGENT_NATIVE_CONFIG__?.clientPlatform) ??
        "web");
}
